<div class="stat-grid"><div class="stat-card"><div><small>Pending</small><strong><?=count(array_filter($q,fn($x)=>$x['status']==='Pending'))?></strong></div></div><div class="stat-card"><div><small>Sent</small><strong><?=count(array_filter($q,fn($x)=>$x['status']==='Sent'))?></strong></div></div><div class="stat-card"><div><small>Failed</small><strong><?=count(array_filter($q,fn($x)=>$x['status']==='Failed'))?></strong></div></div><div class="stat-card"><div><small>Total</small><strong><?=count($q)?></strong></div></div></div>
